import Link from "next/link";
import { getBookletsForSale } from "@/lib/data";
import { getCurrentUser } from "@/lib/session";
import { IconBook } from "@/components/Icons";
import BookletBuyButton from "./BookletBuyButton";
import { href, isLang, type Lang } from "@/lib/lang";
import { pageMeta } from "@/lib/meta";
import { t } from "@/i18n/ui";

type P = { params: Promise<{ lang: string }> };
const langOf = async (params: P["params"]): Promise<Lang> => { const { lang } = await params; return isLang(lang) ? lang : "ar"; };
export async function generateMetadata({ params }: P) {
  const lang = await langOf(params);
  return pageMeta(lang, "/booklets", { title: t(lang).booklets.metaTitle, description: t(lang).booklets.metaDesc });
}

const sar = (h: number) => (h / 100).toLocaleString("en-US", { maximumFractionDigits: 2 });

/** رقم الجوال المحفوظ مقسوم لرمز الدولة والرقم المحلي (لتعبئة نموذج الشراء) */
function splitPhone(p: string | null) {
  if (!p) return { cc: "+966", national: "" };
  for (const cc of ["+966", "+971", "+965", "+973", "+974", "+968"]) if (p.startsWith(cc)) return { cc, national: p.slice(cc.length) };
  return { cc: "أخرى", national: p.replace(/^\+/, "") };
}

export default async function Booklets({ params }: P) {
  const lang = await langOf(params);
  const u = t(lang).booklets;
  const user = await getCurrentUser().catch(() => null);
  const items = await getBookletsForSale(user?.id ?? null);
  return (
    <div className="pub">
      <section className="page-hero">
        <div className="wrap">
          <span className="eyebrow">{u.eyebrow}</span>
          <h1 style={{ fontSize: "clamp(30px,5vw,50px)", marginTop: 12 }}>{u.title}</h1>
          <p className="lead" style={{ maxWidth: 720 }}>{u.lead}</p>
        </div>
      </section>
      <section className="section tight">
        <div className="wrap stack" style={{ ["--space" as string]: "22px" }}>
          <p className="alert info" style={{ margin: 0 }}>{u.included}</p>
          {items.length === 0 ? (
            <div className="card stack">
              <p style={{ margin: 0 }}>{u.empty}</p>
              <Link href={href(lang, "/programs")} className="btn" style={{ width: "fit-content" }}>{u.pricing}</Link>
            </div>
          ) : (
            <ul className="fp-grid" data-testid="booklets-sale">
              {items.map((b) => (
                <li key={b.id} className="card fp-card" data-testid="booklet-card">
                  <div className="fp-cover">
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    {b.cover_id ? <img src={`/api/files/media/${b.cover_id}`} alt={`${u.cover} ${b.title}`} loading="lazy" /> : <span aria-hidden="true"><IconBook size={44} /></span>}
                  </div>
                  <div className="fp-body">
                    <span className="tag soft">PDF · <bdi className="num">{(b.file_size / 1024 / 1024).toFixed(1)}</bdi> {u.mb}</span>
                    <h2>{b.title}</h2>
                    {b.description && <p className="muted" style={{ margin: 0 }}>{b.description}</p>}
                    <p style={{ margin: 0 }}><b className="num" style={{ fontSize: 22 }}>{sar(b.price_halalas)}</b> {lang === "en" ? "SAR" : "ر.س"}</p>
                  </div>
                  <BookletBuyButton id={b.id} price={sar(b.price_halalas)} loggedIn={Boolean(user)} owned={b.owned}
                    pendingOrder={b.pending_order} phone={splitPhone(user?.phone ?? null)} />
                </li>
              ))}
            </ul>
          )}
          <p className="small muted">{u.note} <Link href={href(lang, "/programs")}>{u.programs}</Link>.</p>
        </div>
      </section>
    </div>
  );
}
